Portkey's gateway with `provider="google"` does send `index`, but it's the position inside each chunk, so parallel calls all arrive as `index=0` with a new `id` each. They still end up merged here: `'{"city":"Seattle"}{"city":"San Francisco"}'` under the first id. Could a new `id` start a new call even when `index` is set?

Here's a test through the client that fails on `main`, and as far as I can tell would fail on this branch too. Record it with `PORTKEY_API_KEY` and `GEMINI_API_KEY` set. It could also replace `test_choice_buffer.py`, which tests `ChoiceBuffer` internals:

```python
# conftest.py
@pytest.fixture
def instrument_portkey_with_content(
    tracer_provider, logger_provider, meter_provider
):
    with instrument(
        PortkeyInstrumentor(),
        tracer_provider=tracer_provider,
        logger_provider=logger_provider,
        meter_provider=meter_provider,
        content_capture="SPAN_ONLY",
    ) as instrumentor:
        yield instrumentor


@pytest.fixture
def portkey_gemini_client():
    # `environment` fixture sets placeholder keys for replay.
    return Portkey(
        api_key=os.environ["PORTKEY_API_KEY"],
        provider="google",
        Authorization=os.environ["GEMINI_API_KEY"],
    )


# test_streaming.py
def test_sync_streaming_parallel_tool_calls_gemini(
    span_exporter, portkey_gemini_client, instrument_portkey_with_content, vcr
):
    with vcr.use_cassette("streaming_parallel_tool_calls_gemini.yaml"):
        stream = portkey_gemini_client.chat.completions.create(
            model="gemini-3.5-flash",
            messages=[
                {
                    "role": "user",
                    "content": "What's the weather in Seattle and San Francisco?",
                }
            ],
            tools=[
                {
                    "type": "function",
                    "function": {
                        "name": "get_weather",
                        "parameters": {
                            "type": "object",
                            "properties": {"city": {"type": "string"}},
                            "required": ["city"],
                        },
                    },
                }
            ],
            stream=True,
        )
        tool_calls = [
            tool_call
            for chunk in stream
            for choice in chunk.choices
            for tool_call in choice.delta.tool_calls or []
        ]

    (span,) = span_exporter.get_finished_spans()
    output = json.loads(span.attributes[GenAIAttributes.GEN_AI_OUTPUT_MESSAGES])
    assert [p for p in output[0]["parts"] if p["type"] == "tool_call"] == [
        {
            "type": "tool_call",
            "id": tool_call.id,
            "name": "get_weather",
            "arguments": json.loads(tool_call.function.arguments),
        }
        for tool_call in tool_calls
    ]
```
